import{_ as l,r as t,o as u,c as i,e as p,a as n,s as e,d as s}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Turbo-маршрутизатор - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, как маршрутизируются ссылки с помощью AJAX-фреймворка.","frontmatter":{"subtitle":"Узнайте, как маршрутизируются ссылки с помощью AJAX-фреймворка."},"headers":[{"level":2,"title":"Маршрутизация ссылок","slug":"маршрутизация-ссылок","link":"#маршрутизация-ссылок","children":[]},{"level":2,"title":"Отключение маршрутизации","slug":"отключение-маршрутизации","link":"#отключение-маршрутизации","children":[]},{"level":2,"title":"Отключение для определённых ссылок","slug":"отключение-для-определенных-ссылок","link":"#отключение-для-определенных-ссылок","children":[]},{"level":2,"title":"Отключение прокрутки при переходе","slug":"отключение-прокрутки-при-переходе","link":"#отключение-прокрутки-при-переходе","children":[]},{"level":2,"title":"Сохранение элементов страницы","slug":"сохранение-элементов-страницы","link":"#сохранение-элементов-страницы","children":[]},{"level":2,"title":"Установка корневого пути","slug":"установка-корневого-пути","link":"#установка-корневого-пути","children":[]},{"level":2,"title":"Нативные страницы ошибок","slug":"нативные-страницы-ошибок","link":"#нативные-страницы-ошибок","children":[]},{"level":2,"title":"Кэширование страниц","slug":"кэширование-страниц","link":"#кэширование-страниц","children":[{"level":3,"title":"Прослушивание события кэширования","slug":"прослушивание-события-кэширования","link":"#прослушивание-события-кэширования","children":[]},{"level":3,"title":"Определение загрузки из кэша","slug":"определение-загрузки-из-кэша","link":"#определение-загрузки-из-кэша","children":[]},{"level":3,"title":"Отключение кэширования","slug":"отключение-кэширования","link":"#отключение-кэширования","children":[]}]},{"level":2,"title":"Работа с JavaScript","slug":"работа-с-javascript","link":"#работа-с-javascript","children":[{"level":3,"title":"Встроенные элементы script","slug":"встроенные-элементы-script","link":"#встроенные-элементы-script","children":[]},{"level":3,"title":"Идемпотентность элементов управления","slug":"идемпотентность-элементов-управления","link":"#идемпотентность-элементов-управления","children":[]},{"level":3,"title":"Очистка элементов управления","slug":"очистка-элементов-управления","link":"#очистка-элементов-управления","children":[]},{"level":3,"title":"Приостановка рендеринга","slug":"приостановка-рендеринга","link":"#приостановка-рендеринга","children":[]}]},{"level":2,"title":"Глобальные события","slug":"глобальные-события","link":"#глобальные-события","children":[]},{"level":2,"title":"Примеры использования","slug":"примеры-использования","link":"#примеры-использования","children":[]},{"level":2,"title":"Работа с горячей перезагрузкой","slug":"работа-с-горячеи-перезагрузкои","link":"#работа-с-горячеи-перезагрузкои","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/cms/ajax/turbo-router.md","filePath":"3.x/ru/cms/ajax/turbo-router.md"}'),r={name:"3.x/ru/cms/ajax/turbo-router.md"};function k(d,a,g,h,v,m){const o=t("pre-heading"),c=t("post-heading");return u(),i("div",null,[p(o),a[0]||(a[0]=n("h1",null,"Turbo-маршрутизатор",-1)),p(c),a[1]||(a[1]=e(`<p>Turbo-маршрутизация — это реализация PJAX (push state и AJAX), которая обеспечивает производительность одностраничного приложения без сложности клиентского фреймворка. При клике по ссылке страница автоматически подменяется на стороне клиента без полной перезагрузки.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> turbo <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="маршрутизация-ссылок"><a href="#маршрутизация-ссылок" class="header-anchor">#</a> Маршрутизация ссылок</h2><p>Вы можете программно перейти по ссылке следующим образом.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">visit</span><span class="token punctuation">(</span>location<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы заменить текущий URL без добавления в историю навигации, аналогично <code>window.history.replaceState</code>, установите параметр <code>action</code> в значение <strong>replace</strong>.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">visit</span><span class="token punctuation">(</span>location<span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">action</span><span class="token operator">:</span> <span class="token string">&#39;replace&#39;</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы проверить, включён ли turbo-маршрутизатор и следует ли его использовать.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token keyword">if</span> <span class="token punctuation">(</span>oc<span class="token punctuation">.</span>useTurbo <span class="token operator">&amp;&amp;</span> oc<span class="token punctuation">.</span><span class="token function">useTurbo</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Use PJAX</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="отключение-маршрутизации"><a href="#отключение-маршрутизации" class="header-anchor">#</a> Отключение маршрутизации</h2><p>Чтобы отключить PJAX-маршрутизацию на конкретной странице, можно вызвать полную перезагрузку, добавив мета-тег <code>turbo-visit-control</code> в секцию head страницы со значением <code>reload</code>. Это отключит функцию только для входящих запросов.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-visit-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>reload<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Чтобы полностью отключить PJAX на вашем сайте, установите значение <code>disable</code>. Это отключит функцию для всех входящих и исходящих запросов.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-visit-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>disable<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre></div><h2 id="отключение-для-определенных-ссылок"><a href="#отключение-для-определенных-ссылок" class="header-anchor">#</a> Отключение для определённых ссылок</h2><p>По умолчанию все внутренние HTML-ссылки маршрутизируются через PJAX, но вы можете отключить это, пометив ссылки или их родительский контейнер атрибутом <code>data-turbo=&quot;false&quot;</code>. Отключённые ссылки обрабатываются браузером обычным образом.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-turbo</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Disabled<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы можете повторно включить маршрутизацию, когда родительский элемент её отключил:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">data-turbo</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-turbo</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>true<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Enabled<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="отключение-прокрутки-при-переходе"><a href="#отключение-прокрутки-при-переходе" class="header-anchor">#</a> Отключение прокрутки при переходе</h2><p>Каждый переход прокручивает страницу вверх, как и большинство ссылок в браузере. Однако в некоторых случаях полезно сохранять позицию прокрутки, например, когда ссылки действуют как фильтры. Вы можете отключить прокрутку при переходе с помощью атрибута <code>data-turbo-no-scroll</code> на элементе ссылки.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span> <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-turbo-no-scroll</span><span class="token punctuation">&gt;</span></span>Filter<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="сохранение-элементов-страницы"><a href="#сохранение-элементов-страницы" class="header-anchor">#</a> Сохранение элементов страницы</h2><p>В некоторых случаях вам может потребоваться включить на странице статические элементы, которые не должны обновляться при изменении страницы. Используйте атрибут <code>data-turbo-permanent</code> на родительском элементе. Элемент также должен иметь атрибут <code>id</code>, чтобы исходная страница могла быть сопоставлена с новой, включая обработчики событий.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>main-navigation<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-turbo-permanent</span><span class="token punctuation">&gt;</span></span>...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="установка-корневого-пути"><a href="#установка-корневого-пути" class="header-anchor">#</a> Установка корневого пути</h2><p>По умолчанию PJAX используется для всех ссылок в пределах одного доменного имени, а переход на любой другой URL приводит к полной перезагрузке страницы. В некоторых случаях ваше приложение может находиться в подкаталоге, и ссылки должны применяться только к корневому пути.</p><p>Например, если ваш сайт расположен в <code>/app</code> и вы не хотите, чтобы ссылки применялись к другому сайту в <code>/docs</code>, вы можете ограничить ссылки корневым путём. Установить корневой путь можно, добавив мета-тег <code>turbo-root</code> в секцию head страницы.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-root<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>/app<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="нативные-страницы-ошибок"><a href="#нативные-страницы-ошибок" class="header-anchor">#</a> Нативные страницы ошибок</h2><p>При использовании PJAX, когда сервер отвечает кодом ошибки, например 404 или 500, полный HTML-элемент заменяется целиком, включая скрипты и стили. Это предотвращает случайную замену body контентом, созданным другим приложением.</p><p>Вы можете отключить это поведение, добавив мета-тег <code>turbo-visit-control</code> в секцию head страницы со значением <code>error</code>. Это сообщит turbo-маршрутизатору, что содержимое страницы ошибки создаётся нативным приложением.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-visit-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>error<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="кэширование-страниц"><a href="#кэширование-страниц" class="header-anchor">#</a> Кэширование страниц</h2><p>С включённым кэшированием turbo-маршрутизатор повышает производительность сайта, отображая ранее посещённые страницы без обращения к сети, что делает сайт быстрее. При клике по ссылке содержимое показывается из локального хранилища браузера, пока страница запрашивается в фоновом режиме. Последняя версия страницы отображается после завершения сетевого запроса, что означает двойной рендеринг страницы.</p><h3 id="прослушивание-события-кэширования"><a href="#прослушивание-события-кэширования" class="header-anchor">#</a> Прослушивание события кэширования</h3><p>Вы можете слушать событие <code>page:before-cache</code>, если нужно подготовить документ перед помещением в кэш. Это можно использовать для сброса форм, сворачивания элементов интерфейса или очистки сторонних элементов управления, чтобы страница была готова к повторному отображению.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;page:before-cache&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Close any open submenus, etc.</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="определение-загрузки-из-кэша"><a href="#определение-загрузки-из-кэша" class="header-anchor">#</a> Определение загрузки из кэша</h3><p>Вы можете определить, когда содержимое страницы получено из кэша, по атрибуту <code>data-turbo-preview</code> на HTML-элементе. В JavaScript это выглядит так:</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token keyword">if</span> <span class="token punctuation">(</span>document<span class="token punctuation">.</span>documentElement<span class="token punctuation">.</span><span class="token function">hasAttribute</span><span class="token punctuation">(</span><span class="token string">&#39;data-turbo-preview&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Page shown is loaded from cache</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Или с помощью стилей:</p><div class="language-css extra-class"><pre class="language-css"><code><span class="token selector">html[data-turbo-preview]</span> <span class="token punctuation">{</span>
    <span class="token comment">/* Hide overlays from previous view */</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="отключение-кэширования"><a href="#отключение-кэширования" class="header-anchor">#</a> Отключение кэширования</h3><p>Вы можете отключить кэширование для отдельных страниц с помощью мета-тега <code>turbo-cache-control</code> в секции head страницы. Установка значения <strong>no-cache</strong> полностью отключит кэш. Вы также можете установить значение <strong>no-preview</strong>, чтобы сохранить кэшированную версию при навигации кнопками «Назад» и «Вперёд» браузера.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>head</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>meta</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>turbo-cache-control<span class="token punctuation">&quot;</span></span> <span class="token attr-name">content</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>no-cache<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>head</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="работа-с-javascript"><a href="#работа-с-javascript" class="header-anchor">#</a> Работа с JavaScript</h2><p>При работе с PJAX содержимое страницы может загружаться динамически, что отличается от обычного поведения браузера. Для решения этой проблемы используется обработчик события <code>render</code>, который вызывается каждый раз при загрузке страницы, включая <a href="./update-partials.html">AJAX-обновления</a>.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;render&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Page has rendered something new</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Функция <code>oc.pageReady</code> используется для вызова кода, когда страница и скрипты готовы. Функция возвращает промис, который разрешается после загрузки всех скриптов страницы или немедленно, если они уже загружены.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">pageReady</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    <span class="token comment">// Page has finished loading scripts</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Ещё одна полезная функция — <code>oc.waitFor</code>, которая ждёт появления объекта или переменной. Функция возвращает промис, который разрешается при обнаружении переменной.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">waitFor</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> window<span class="token punctuation">.</span>propName<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
    <span class="token comment">// window.propName is now available</span>
<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Второй аргумент задаёт интервал ожидания в миллисекундах. Следующий пример прекратит ожидание через две секунды.</p><div class="language-js extra-class"><pre class="language-js"><code>oc<span class="token punctuation">.</span><span class="token function">waitFor</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> window<span class="token punctuation">.</span>propName<span class="token punctuation">,</span> <span class="token number">2000</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">then</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&#39;Found the variable!&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">catch</span><span class="token punctuation">(</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    console<span class="token punctuation">.</span><span class="token function">error</span><span class="token punctuation">(</span><span class="token string">&#39;Gave up waiting...&#39;</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="встроенные-элементы-script"><a href="#встроенные-элементы-script" class="header-anchor">#</a> Встроенные элементы script</h3><p>Turbo-маршрутизатор поддерживает скрипты в теге <code>&lt;head&gt;</code> страницы, сравнивая различия. Если вы используете теги script в теге <code>&lt;body&gt;</code>, скрипт будет выполняться каждый раз при рендеринге страницы, что может быть нежелательно.</p><p>Вы можете добавить <code>data-turbo-eval=&quot;false&quot;</code>, чтобы скрипт выполнялся только при первой загрузке страницы. Скрипт не будет вызываться для PJAX-запросов.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">data-turbo-eval</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>false<span class="token punctuation">&quot;</span></span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{{ [&#39;@framework.bundle&#39;]|theme }}<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block tip"><p>Если вы размещаете скрипты в теге <code>&lt;body&gt;</code> для повышения производительности, рассмотрите перенос их в тег <code>&lt;head&gt;</code> с использованием <code>&lt;script defer&gt;</code>.</p></div><p>Чтобы выполнить встроенный JavaScript-код только один раз, независимо от первой загрузки страницы или PJAX-запроса, установите уникальное значение атрибута <code>data-turbo-eval-once</code>. Уникальное значение (например, <code>myAjaxPromise</code>) используется для определения, был ли скрипт уже обработан.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span> <span class="token attr-name">data-turbo-eval-once</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myAjaxPromise<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript">
    <span class="token comment">// This script will run once only</span>
    <span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;ajax:promise&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="идемпотентность-элементов-управления"><a href="#идемпотентность-элементов-управления" class="header-anchor">#</a> Идемпотентность элементов управления</h3><div class="custom-block aside"><p>October CMS предоставляет вспомогательную библиотеку для простого создания <a href="./hot-controls.html">идемпотентных элементов управления</a>.</p></div><p>При переходе на страницу и инициализации JavaScript-компонентов важно, чтобы эти функции были идемпотентными. Простыми словами, идемпотентная функция безопасна для многократного вызова без изменения результата после первого применения.</p><p>Один из способов сделать функцию идемпотентной — отслеживать, была ли она уже выполнена, добавляя значение в свойство <code>dataset</code> каждого обработанного элемента. Это полезно для внешних скриптов.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;page:loaded&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Find my control</span>
    <span class="token keyword">var</span> myControl <span class="token operator">=</span> document<span class="token punctuation">.</span><span class="token function">querySelector</span><span class="token punctuation">(</span><span class="token string">&#39;.my-control&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// Check if control has already been initialized</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span>myControl<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>hasMyControl<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        myControl<span class="token punctuation">.</span>dataset<span class="token punctuation">.</span>hasMyControl <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>

        <span class="token comment">// Initialize since this is the first time</span>
        <span class="token function">initializeMyControl</span><span class="token punctuation">(</span>myControl<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>В качестве общего совета — более простой подход заключается в том, чтобы позволить функции выполняться многократно и применять техники идемпотентности внутри. Например, проверить, существует ли разделитель меню, прежде чем создавать новый.</p><h3 id="очистка-элементов-управления"><a href="#очистка-элементов-управления" class="header-anchor">#</a> Очистка элементов управления</h3><p>В некоторых случаях вы можете привязывать глобальные события только для конкретной страницы, например, привязать горячую клавишу к определённому действию.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;keydown&#39;</span><span class="token punctuation">,</span> myKeyDownFunction<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Чтобы предотвратить утечку этого события на другие страницы, следует удалить событие с помощью метода <code>page:unload</code>, который уничтожает все события и элементы управления. Событие можно использовать однократно для безопасной очистки элементов управления и событий.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;page:unload&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token function">removeEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;keydown&#39;</span><span class="token punctuation">,</span> myKeyDownFunction<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span> <span class="token punctuation">{</span> <span class="token literal-property property">once</span><span class="token operator">:</span> <span class="token boolean">true</span> <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>October CMS включает вспомогательную библиотеку для <a href="./hot-controls.html">создания одноразовых элементов управления</a>.</p></div><h3 id="приостановка-рендеринга"><a href="#приостановка-рендеринга" class="header-anchor">#</a> Приостановка рендеринга</h3><p>Если вы хотите анимировать элементы, такие как выпадающие меню или меню за пределами экрана, перед загрузкой новой страницы, вы можете приостановить событие <code>page:before-render</code>, предотвратив поведение по умолчанию и возобновив его с помощью функции <code>resume()</code> из данных события.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;page:before-render&#39;</span><span class="token punctuation">,</span> <span class="token keyword">async</span> <span class="token punctuation">(</span><span class="token parameter">event</span><span class="token punctuation">)</span> <span class="token operator">=&gt;</span> <span class="token punctuation">{</span>
    event<span class="token punctuation">.</span><span class="token function">preventDefault</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">await</span> <span class="token function">animateOut</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    event<span class="token punctuation">.</span>detail<span class="token punctuation">.</span><span class="token function">resume</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block warning"><p>Имейте в виду, что событие <strong>page:before-render</strong> может сработать дважды: один раз из кэша и ещё раз после запроса нового содержимого страницы.</p></div><h2 id="глобальные-события"><a href="#глобальные-события" class="header-anchor">#</a> Глобальные события</h2><p>AJAX-фреймворк генерирует несколько событий во время жизненного цикла навигации и ответов страниц. События обычно генерируются на объекте <code>document</code>, а данные доступны через свойство <code>event.detail</code>.</p><div class="table"><table tabindex="0"><thead><tr><th>Событие</th><th>Описание</th></tr></thead><tbody><tr><td><strong>render</strong></td><td>генерируется при обновлении страницы через PJAX или AJAX.</td></tr><tr><td><strong>page:click</strong></td><td>генерируется при клике на ссылку с turbo-маршрутизацией.</td></tr><tr><td><strong>page:before-visit</strong></td><td>генерируется перед переходом по адресу, за исключением навигации через историю браузера.</td></tr><tr><td><strong>page:visit</strong></td><td>генерируется после начала перехода по клику.</td></tr><tr><td><strong>page:request-start</strong></td><td>генерируется перед запросом страницы.</td></tr><tr><td><strong>page:request-end</strong></td><td>генерируется после завершения запроса страницы.</td></tr><tr><td><strong>page:before-cache</strong></td><td>генерируется перед кэшированием страницы.</td></tr><tr><td><strong>page:before-render</strong></td><td>генерируется перед рендерингом содержимого страницы.</td></tr><tr><td><strong>page:render</strong></td><td>генерируется после рендеринга страницы. Срабатывает дважды: один раз из кэша и ещё раз после запроса нового содержимого.</td></tr><tr><td><strong>page:load</strong></td><td>генерируется один раз после начальной загрузки страницы и повторно при каждом переходе.</td></tr><tr><td><strong>page:loaded</strong></td><td>аналогично <code>page:load</code>, но ожидает загрузки всех новых скриптов.</td></tr><tr><td><strong>page:updated</strong></td><td>аналогично <code>DOMContentLoaded</code>, но генерируется только при переходе на страницу.</td></tr><tr><td><strong>page:unload</strong></td><td>вызывается, когда ранее загруженная страница должна быть очищена.</td></tr></tbody></table></div><h2 id="примеры-использования"><a href="#примеры-использования" class="header-anchor">#</a> Примеры использования</h2><p>Следующий JavaScript будет выполняться каждый раз при загрузке страницы, включая скрипты.</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token function">addEventListener</span><span class="token punctuation">(</span><span class="token string">&#39;page:loaded&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="работа-с-горячеи-перезагрузкои"><a href="#работа-с-горячеи-перезагрузкои" class="header-anchor">#</a> Работа с горячей перезагрузкой</h2>`,85)),a[2]||(a[2]=n("p",null,[s("В некоторых случаях turbo-маршрутизатор может мешать при разработке сайта с горячей перезагрузкой или технологией синхронизации браузера, например, при использовании "),n("a",{href:"https://laravel-mix.com/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Laravel Mix"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(" в режиме разработки с "),n("code",null,"laravel-mix & browsersync"),s(". Для решения этой проблемы добавьте следующий код в конфигурацию "),n("code",null,"browserSync"),s(" вашего webpack.")],-1)),a[3]||(a[3]=e(`<div class="language-js extra-class"><pre class="language-js"><code><span class="token literal-property property">snippetOptions</span><span class="token operator">:</span> <span class="token punctuation">{</span>
    <span class="token literal-property property">rule</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token literal-property property">match</span><span class="token operator">:</span> <span class="token regex"><span class="token regex-delimiter">/</span><span class="token regex-source language-regex">&lt;\\/head&gt;</span><span class="token regex-delimiter">/</span><span class="token regex-flags">i</span></span><span class="token punctuation">,</span>
        <span class="token function-variable function">fn</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token parameter">snippet<span class="token punctuation">,</span> match</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token string">&#39;&lt;meta name=&quot;turbo-visit-control&quot; content=&quot;disable&quot; /&gt;&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
   <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./hot-controls.html">Наблюдаемые элементы управления</a></li></ul></div>`,3))])}const q=l(r,[["render",k]]);export{b as __pageData,q as default};
